#!/bin/bash
set -euo pipefail

PROJECT_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$PROJECT_ROOT"
if [[ -z "${DEVELOPER_DIR:-}" && -d /Applications/Xcode.app/Contents/Developer ]]; then
    export DEVELOPER_DIR=/Applications/Xcode.app/Contents/Developer
fi

xcrun swift build --configuration release --product FellowMac
BIN_DIR="$(xcrun swift build --configuration release --show-bin-path)"
APP_PATH="$PROJECT_ROOT/dist/Fellow Mac.app"
mkdir -p "$PROJECT_ROOT/dist"
# Replace only the bundle generated by this script.
rm -rf "$APP_PATH"
mkdir -p "$APP_PATH/Contents/MacOS" "$APP_PATH/Contents/Resources"
cp "$BIN_DIR/FellowMac" "$APP_PATH/Contents/MacOS/FellowMac"
if [[ ! -f Resources/AppIcon.icns ]]; then
    xcrun swift scripts/make-icon.swift Resources/AppIcon.icns
fi
cp Resources/AppIcon.icns "$APP_PATH/Contents/Resources/"
cp Resources/Info.plist "$APP_PATH/Contents/Info.plist"
cp LICENSE THIRD_PARTY_NOTICES.md "$APP_PATH/Contents/Resources/"
chmod 755 "$APP_PATH/Contents/MacOS/FellowMac"
/usr/bin/plutil -lint "$APP_PATH/Contents/Info.plist"
# Local ad-hoc signing. Public distribution requires a separate signing workflow.
/usr/bin/codesign --force --sign - --timestamp=none "$APP_PATH"
/usr/bin/codesign --verify --strict "$APP_PATH"
printf 'Bundle created: %s\n' "$APP_PATH"
